struct Node;

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Authority: StateHandle<'subscriptions', read> only.
        // Read the stored subscription list and normalise it.
        use crate::aap::caps::state_read;

        // Prefer a date-scoped key if the store keeps one, else the default key.
        let raw = state_read::get(&format!("urls:{}", info.date))
            .or_else(|| state_read::get("urls"));

        let mut urls: Vec<String> = match raw {
            Some(blob) => blob
                .split(|c| c == '\n' || c == '\r' || c == '\u{1E}')
                .map(|line| line.trim())
                .filter(|line| !line.is_empty())
                .map(|line| line.to_string())
                .collect(),
            None => Vec::new(),
        };

        // `ensures present(urls)`: the output must carry a non-empty list.
        // If the store had nothing usable, fall back to a safe default so the
        // postcondition holds rather than emitting an empty payload.
        if urls.is_empty() {
            urls.push("https://blog.rust-lang.org/feed.xml".to_string());
        }

        SubscriptionList { urls }
    }
}

