use crate::aap::caps::state_read;

struct Node;

/// Parse a JSON array of strings, e.g. `["a", "b"]`. Returns None if the
/// text is not a well-formed array of strings.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' if out.is_empty() => break,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            '"' => cur.push('"'),
                            '\\' => cur.push('\\'),
                            '/' => cur.push('/'),
                            'n' => cur.push('\n'),
                            'r' => cur.push('\r'),
                            't' => cur.push('\t'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                            _ => return None,
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
                while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
                    chars.next();
                }
                match chars.next()? {
                    ',' => continue,
                    ']' => break,
                    _ => return None,
                }
            }
            _ => return None,
        }
    }
    Some(out)
}

fn parse_urls(blob: &str) -> Vec<String> {
    let candidates: Vec<String> = match parse_json_string_array(blob) {
        Some(list) => list,
        None => blob
            .split(|c| c == '\n' || c == '\r' || c == '\u{1E}' || c == ',')
            .map(|s| s.to_string())
            .collect(),
    };

    let mut urls: Vec<String> = Vec::new();
    for c in candidates {
        let t = c.trim();
        if t.is_empty() || t.starts_with('#') {
            continue;
        }
        if !urls.iter().any(|u| u == t) {
            urls.push(t.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Authority: StateHandle<'subscriptions', read> only.
        // Return exactly what the store holds; never fabricate URLs, since
        // downstream fetches are confined to an allowlist this node cannot see.
        let raw = state_read::get(&format!("urls:{}", info.date))
            .or_else(|| state_read::get("urls"))
            .or_else(|| state_read::get("subscriptions"));

        let urls = match raw {
            Some(blob) => parse_urls(&blob),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

